#!/usr/bin/env bash
# Pushes the Kiosk Process live-update fix:
#  - app/blueprints/instances.py
#      * GET .../kiosk/status now LONG-POLLS (?wait=<s>&sig=<last sig>),
#        the same pattern as the Agent's own get_pending_command channel
#        in agent_api.py: it holds the connection open and re-checks every
#        ~0.5s, returning the instant something actually changes instead
#        of on a flat interval. Updates land within about half a second of
#        the DB changing, from any source (this tab, another admin's tab,
#        or the Agent's heartbeat/ack).
#      * kiosk_start/stop/restart return JSON (incl. that same signature)
#        when called via fetch, instead of always redirecting.
#  - app/templates/instances/detail.html
#      * "Stopped" pill is red instead of amber.
#      * Start/Stop/Restart submit via fetch (no full page POST).
#      * The panel keeps one long-poll request open at a time and re-opens
#        it immediately on each response, instead of polling every 3s.
#
# Run from inside /root/admin_panel.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"

for req in app requirements.txt run.py; do
    if [ ! -e "$req" ]; then
        echo "Error: expected to find '$req' here - run this from the admin_panel repo root."
        exit 1
    fi
done

TS="$(date +%Y%m%d_%H%M%S)"
mkdir -p "backups/$TS"
cp app/blueprints/instances.py "backups/$TS/instances.py.bak" 2>/dev/null || true
cp app/templates/instances/detail.html "backups/$TS/detail.html.bak" 2>/dev/null || true
echo "==> Backed up existing files to backups/$TS/"

echo "==> Writing app/blueprints/instances.py"
base64 -d > app/blueprints/instances.py << 'INSTANCES_PY_B64'

INSTANCES_PY_B64

echo "==> Writing app/templates/instances/detail.html"
base64 -d > app/templates/instances/detail.html << 'DETAIL_HTML_B64'

DETAIL_HTML_B64

echo "==> Verifying"
python3 -c "import ast; ast.parse(open('app/blueprints/instances.py').read())"
echo "    instances.py: syntax OK"

echo ""
echo "==> Restarting the admin panel app"
pkill -f "admin_panel/run.py" 2>/dev/null || true
fuser -k 6090/tcp 2>/dev/null || true
sleep 1
source venv/bin/activate
nohup python run.py > app.log 2>&1 &
disown
sleep 2
tail -n 15 app.log

echo ""
echo "Done. Note: app.run(..., threaded=True) in run.py is required for this"
echo "to work (each open long-poll connection ties up one request slot) -"
echo "it's already set, this is just a heads-up if that ever changes."
echo ""
echo "Open an instance's detail page and check the Kiosk Process panel:"
echo "  - Stopped now shows red"
echo "  - Start/Stop/Restart update the panel immediately, no page reload"
echo "  - Any status change lands on the page within ~1s, not on a 3s timer"
